def build(b):
    for level in range(1, 6):
        for passage, questions in P[level]:
            for prompt, correct, wrong, expl in questions:
                b.mc(M, level, prompt, correct, wrong, expl, passage=passage)
        for sentence, blanks, distr, expl in FILL[level]:
            b.fill(M, level, "Completa la frase amb les paraules correctes", sentence, blanks, distr, expl)
